```ts
import type { AnimationGroup } from "@babylonjs/lite";
import { removeAnimationGroup, addAnimationGroup, playAnimation } from "@babylonjs/lite";

export function freezeForPosing(group: AnimationGroup): () => void {
    const manager = group._animationManager;
    if (manager) {
        removeAnimationGroup(manager, group);
    }

    return () => {
        if (manager) {
            addAnimationGroup(manager, group);
            playAnimation(group);
        }
    };
}
```

This is clean and handles both property groups and glTF groups correctly. By removing the group from the manager, no updates are applied to it, so the user can freely set node transforms. On resume, the group is re-added (preserving its position in the task order per note 29) and playAnimation ensures it's in a playing state.
